BLOCK = "  # sdr-stabil: Selbstheilung, Heilungen, USB -71. Nur lesen.\n  if [[ -f \"$APP/sdr_stabil.json\" ]]; then\n    ok \"Selbstheilung\" \"aktiv\"\n    H24=\"$(python3 -c 'import json,sys; print(int(json.load(open(sys.argv[1])).get(\"heilung_24h\") or 0))' \"$APP/sdr_stabil.json\" 2>/dev/null || echo 0)\"\n    ok \"Heilungen 24h\" \"$H24\"\n    U71=\"$(python3 -c 'import json,sys; print(int(json.load(open(sys.argv[1])).get(\"usb71\") or 0))' \"$APP/sdr_stabil.json\" 2>/dev/null || echo 0)\"\n    if [[ \"$U71\" -gt 5 ]]; then warn \"USB -71\" \"$U71\" \"aktiver Hub mit Netzteil noetig\"\n    else ok \"USB -71\" \"$U71\"; fi\n  else\n    warn \"Selbstheilung\" \"Zustandsdatei fehlt\" \"prepper-sdr neu starten\"\n  fi\n\n"

def sha(data):
    return hashlib.sha256(data).hexdigest()

def fenster(jetzt):
    jetzt = jetzt.astimezone(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin %s Minute %02d" % (jetzt.strftime("%H:%M"), jetzt.minute)

def tausch(data, old, new):
    if new in data:
        return data
    if data.count(old) != 1:
        raise RuntimeError("stelle")
    return data.replace(old, new, 1)

def laden():
    return json.loads(PAYLOAD_TEXT)

def fullcheck_neu(text):
    if 'FC_VERSION="2.4"' not in text or "flugfunk-6: Kanaele" not in text:
        raise RuntimeError("version")
    if 'FC_VERSION="2.5"' in text and "sdr-stabil: Selbstheilung" in text:
        return text
    neu = text.replace('FC_VERSION="2.4"', 'FC_VERSION="2.5"', 1)
    anker = "  # --- SDR-Watchdog (Datenlage der Sticks, nur lesen)\n"
    if anker not in neu:
        raise RuntimeError("anker")
    neu = neu.replace(anker, BLOCK + anker, 1)
    if "# fullcheck.sh Basis flugfunk-6" in neu:
        neu = neu.replace("# fullcheck.sh Basis flugfunk-6", "# fullcheck.sh Basis sdr-stabil", 1)
    elif "Basis sdr-stabil" not in neu:
        neu = neu.replace("# fullcheck.sh", "# fullcheck.sh Basis sdr-stabil", 1)
    return neu

def reihenfolge():
    print("Reihenfolge der Endstaende:")
    print("1. apply-logbericht.py: prepper_log.py 545c2448bbe46a04/17276, fullcheck 2.3, dashboard mit logbericht aktiv")
    print("2. apply-flugfunk-6.py: flugfunk.py 763880da5141e2d5/83747, fullcheck 2.4, Stream /api/flugfunk/stream")
    print("3. apply-sdr-stabil.py: prepper_sdr.py, prepper_log.py, fullcheck 2.5")

def sichern(path, data, ende):
    path = Path(path)
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-" + ende + "-*"))
    bak = Path(str(path) + ".bak-" + ende + "-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path, data, ende):
    path = Path(path)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-" + ende)
    if tmp.exists():
        raise RuntimeError("temporaer")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner, dry, kein, jetzt=None, hashcheck=True, fullcheck_hash=None, full_pfad=None):
    reihenfolge()
    print("prepper-sdr Neustart noetig: Selbstheilung, Prioritaet und RDS-PPM laufen im SDR-Prozess.")
    print("Ein Pi-Neustart wird nicht ausgefuehrt.")
    ordner = Path(ordner)
    roh = laden()
    ziel = {}
    for name in ("prepper_sdr.py", "prepper_log.py"):
        pfad = ordner / name
        if not pfad.is_file():
            print("STOP: %s fehlt" % pfad)
            return 2
        data = pfad.read_bytes()
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
        kopf, laenge = FEST[name]
        if hashcheck and (not sha(data).startswith(kopf) or len(data) != laenge):
            print("STOP: %s ist nicht der Stand nach flugfunk-6" % name)
            print("Live-Hash sha256 %s" % sha(data))
            return 2
        try:
            neu = data
            schluessel = "sdr" if name == "prepper_sdr.py" else "log"
            for paar in roh[schluessel]:
                neu = tausch(neu, base64.b64decode(paar["old"]), base64.b64decode(paar["new"]))
            if hashcheck:
                compile(neu, name, "exec")
        except (RuntimeError, SyntaxError) as exc:
            print("STOP: Stelle unbekannt (%s). Nichts geschrieben." % type(exc).__name__)
            return 2
        ziel[name] = (pfad, data, neu)
        print("%s endstand sha16 %s bytes %d" % (name, sha(neu)[:16], len(neu)))
    if hashcheck:
        for name in ("flugfunk.py", "pushover_push.py"):
            pfad = ordner / name
            if not pfad.is_file():
                print("STOP: %s fehlt" % pfad)
                return 2
            data = pfad.read_bytes()
            kopf, laenge = FEST[name]
            print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
            if not sha(data).startswith(kopf) or len(data) != laenge:
                print("STOP: %s gehoert nicht zum Endstand nach flugfunk-6" % name)
                print("Live-Hash sha256 %s" % sha(data))
                return 2
        dash = ordner / "dashboard.py"
        if not dash.is_file():
            print("STOP: dashboard.py fehlt")
            return 2
        roh_dash = dash.read_bytes()
        print("dashboard.py sha16 %s bytes %d, unveraendert" % (sha(roh_dash)[:16], len(roh_dash)))
        if b"logbericht aktiv" not in roh_dash or b"_ff_stream" not in roh_dash:
            print("STOP: dashboard.py ist nicht der Stand nach logbericht und flugfunk-6")
            return 2
    fc_pfad = Path(full_pfad) if full_pfad else FULL
    if not fc_pfad.is_file():
        print("STOP: fullcheck.sh fehlt")
        return 2
    fc_alt = fc_pfad.read_bytes()
    print("fullcheck.sh sha256 %s bytes %d" % (sha(fc_alt), len(fc_alt)))
    try:
        fc = fullcheck_neu(fc_alt.decode("utf-8")).encode()
    except (RuntimeError, UnicodeError) as exc:
        print("STOP: fullcheck ist nicht 2.4 (%s). Nichts geschrieben." % type(exc).__name__)
        print("Live-Hash sha256 %s" % sha(fc_alt))
        return 2
    print("fullcheck.sh endstand sha16 %s bytes %d" % (sha(fc)[:16], len(fc)))
    if fullcheck_hash != sha(fc_alt):
        print("STOP: fullcheck bestaetigen mit --fullcheck-hash %s" % sha(fc_alt))
        return 2
    gleich = all(alt == neu for _p, alt, neu in ziel.values()) and fc_alt == fc
    if gleich:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    frei, meldung = fenster(jetzt or datetime.now().astimezone())
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    for pfad, alt, neu in ziel.values():
        if alt != neu:
            sichern(pfad, alt, "sdrstabil")
            schreiben(pfad, neu, "sdrstabil")
    sichern(fc_pfad, fc_alt, "sdrstabil")
    schreiben(fc_pfad, fc, "sdrstabil")
    print("geschrieben. flugfunk.py, pushover_push.py und dashboard.py unveraendert.")
    if kein:
        print("kein Neustart. prepper-sdr muss spaeter neu starten, sonst heilt der laufende Prozess nicht.")
        return 0
    if str(ordner) != "/home/fmg/prepper-dashboard":
        print("Testordner, kein systemctl")
        return 0
    for dienst in ("prepper-dashboard.service", "prepper-sdr.service"):
        subprocess.run(["systemctl", "restart", dienst], check=False)
        print("Neustart %s" % dienst)
    return 0

def _modul(name, pfad):
    spec = importlib.util.spec_from_file_location(name, pfad)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod

def selftest():
    roh = laden()
    ordner = Path(tempfile.mkdtemp(prefix="sdrstabil-"))
    try:
        (ordner / "prepper_sdr.py").write_bytes(base64.b64decode(roh["sdr_alt"]))
        (ordner / "prepper_log.py").write_bytes(base64.b64decode(roh["log_alt"]))
        fc = "# fullcheck.sh Basis flugfunk-6\nFC_VERSION=\"2.4\"\nflugfunk-6: Kanaele\n3916f7d880b13569\n  # --- SDR-Watchdog (Datenlage der Sticks, nur lesen)\n"
        fp = ordner / "fullcheck.sh"
        fp.write_text(fc)
        vorher = (ordner / "prepper_sdr.py").read_bytes()
        assert apply_dir(ordner, True, True, hashcheck=False, fullcheck_hash=sha(fc.encode()), full_pfad=fp) == 0
        assert (ordner / "prepper_sdr.py").read_bytes() == vorher
        von = datetime(2026, 11, 26, 18, 4, tzinfo=ZoneInfo("Europe/Berlin"))
        assert apply_dir(ordner, False, False, jetzt=von, hashcheck=False, fullcheck_hash=sha(fc.encode()), full_pfad=fp) == 2
        assert (ordner / "prepper_sdr.py").read_bytes() == vorher and 'FC_VERSION="2.4"' in fp.read_text()
        innen = datetime(2026, 11, 26, 18, 10, tzinfo=ZoneInfo("Europe/Berlin"))
        assert apply_dir(ordner, False, True, jetzt=innen, hashcheck=False, fullcheck_hash=sha(fc.encode()), full_pfad=fp) == 0
        sdr_neu = (ordner / "prepper_sdr.py").read_bytes()
        log_neu = (ordner / "prepper_log.py").read_bytes()
        compile(sdr_neu, "prepper_sdr.py", "exec")
        compile(log_neu, "prepper_log.py", "exec")
        assert _modul("logstabil_probe", ordner / "prepper_log.py").selftest() == "logbericht ok"
        text = sdr_neu.decode("utf-8")
        helfer = text[text.index("def _wd_helper"):text.index("\ndef wd_helper_state")]
        block = text[text.index("# ===== sdrStabil"):text.index('return "sdr-stabil ok"\n') + len('return "sdr-stabil ok"\n')]
        ns = {"__name__": "probe"}
        stub = (
            "import os, json, time, subprocess, shutil, tempfile\n"
            "_WD = {'live': False}\n"
            "def cfg_serial(cfg):\n    return '90000002'\n"
            "def _fc_act(*_a):\n    return None\n"
            "class Planner:\n"
            "    def _cmd_rds(self, f):\n        return [['rtl_fm', '-f', '102.0M', '-p', '1', '-g', '40', '-']]\n"
            "    def start(self, what):\n        self.procs = []\n"
            "    def step(self):\n        return None\n"
        )
        exec(compile(stub + helfer + "\n" + block, "sdr-stabil-probe.py", "exec"), ns)
        assert ns["selftest_stabil"]() == "sdr-stabil ok"
        assert 'FC_VERSION="2.5"' in fp.read_text() and "USB -71" in fp.read_text() and "Heilungen 24h" in fp.read_text()
    finally:
        shutil.rmtree(ordner, ignore_errors=True)
    return "sdr-stabil ok"

